import 'dart:io';

/// Regenerates `lib/src/cli/hub_templates.g.dart` from the files in
/// `tool/hub/`, so `omni hub install` writes them from a compiled binary
/// that runs without the repo next to it.
///
/// Run from `packages/omniflow_engine`: `dart run tool/hub/embed_templates.dart`,
/// or with `--check` to fail when the generated file is stale.
const templatesDir = 'tool/hub';
const outputPath = 'lib/src/cli/hub_templates.g.dart';

String generateHubTemplates(Directory dir) {
  final files =
      dir
          .listSync()
          .whereType<File>()
          .where((f) => !f.path.endsWith('.dart'))
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));
  final out = StringBuffer()
    ..writeln(
      '// GENERATED by tool/hub/embed_templates.dart from tool/hub/. Do not edit.',
    )
    ..writeln()
    ..writeln('/// The files omni hub install writes, keyed by file name.')
    ..writeln('const hubTemplates = <String, String>{');
  for (final file in files) {
    final name = file.uri.pathSegments.last;
    final source = file.readAsStringSync();
    if (source.contains("'''")) {
      throw StateError('$name contains a triple quote and cannot be embedded');
    }
    out
      ..writeln("  '$name': r'''")
      ..write(source)
      ..writeln("''',");
  }
  out.writeln('};');
  return out.toString();
}

void main(List<String> args) {
  final generated = generateHubTemplates(Directory(templatesDir));
  if (args.contains('--check')) {
    final current = File(outputPath).existsSync()
        ? File(outputPath).readAsStringSync()
        : '';
    if (current != generated) {
      stderr.writeln(
        '$outputPath is stale. Run: dart run tool/hub/embed_templates.dart',
      );
      exitCode = 1;
    }
    return;
  }
  File(outputPath).writeAsStringSync(generated);
}
